question:
以下 JS 代码输出什么？
```js
var a = 1;
function f() { console.log(a); var a = 2; }
f();
```

以下 JS 代码输出什么？
```js
let x = 10;
const f = () => { console.log(x); x = 20; };
f(); console.log(x);
```

以下 JS 代码输出什么（闭包）？
```js
function make() {
  let n = 0;
  return () => ++n;
}
const a = make(); const b = make();
console.log(a(), a(), b());
```

以下 JS 代码输出什么（var 循环捕获）？
```js
const fns = [];
for (var i = 0; i < 3; i++) fns.push(() => console.log(i));
fns[0]();
```

以下 JS 代码输出什么（let 循环捕获）？
```js
const fns = [];
for (let i = 0; i < 3; i++) fns.push(() => console.log(i));
fns[1]();
```

以下 JS 代码输出什么（严格模式 this）？
```js
'use strict';
function f() { console.log(this); }
f();
```

以下 JS 代码输出什么（对象方法 this）？
```js
const o = { v: 5, get() { return this.v; } };
console.log(o.get());
const g = o.get;
console.log(g());
```

以下 JS 代码输出什么（原型链）？
```js
function A() {}
A.prototype.x = 1;
const a = new A();
console.log(a.x, a.hasOwnProperty('x'));
```

以下 JS 代码输出什么（class 继承）？
```js
class A { constructor() { this.v = 'a'; } }
class B extends A { constructor() { super(); this.v += 'b'; } }
console.log(new B().v);
```

以下 JS 代码输出什么（Object.create）？
```js
const base = { greet() { return 'hi'; } };
const o = Object.create(base);
console.log(o.greet(), o.hasOwnProperty('greet'));
```

以下 JS 代码输出什么（getter）？
```js
const o = { get v() { return 7; } };
console.log(o.v);
```

以下 JS 代码输出什么（Symbol.iterator）？
```js
const o = { [Symbol.iterator]: function* () { yield 1; yield 2; } };
console.log([...o].length);
```

以下 JS 代码输出什么（Object.assign 浅拷贝）？
```js
const a = { x: { y: 1 } };
const b = Object.assign({}, a);
b.x.y = 9;
console.log(a.x.y);
```

以下 JS 代码输出什么（静态方法）？
```js
class A { static s() { return 's'; } }
console.log(A.s());
```

以下 JS 代码输出什么（instanceof 跨原型）？
```js
function A() {}
const a = new A();
console.log(a instanceof A, a instanceof Object);
```

以下 JS 代码输出顺序是什么（microtask 优先）？
```js
console.log(1);
Promise.resolve().then(() => console.log(2));
setTimeout(() => console.log(3), 0);
console.log(4);
```

以下 JS 代码输出什么（async/await）？
```js
async function f() { return 42; }
f().then(v => console.log(v));
```

以下 JS 代码输出什么（async 内 throw）？
```js
async function f() { throw new Error('boom'); }
f().catch(e => console.log(e.message));
```

以下 JS 代码输出什么（微任务嵌套）？
```js
Promise.resolve().then(() => console.log(1))
  .then(() => console.log(2));
Promise.resolve().then(() => console.log(3));
```

以下 JS 代码输出什么（Promise 构造函数立即执行）？
```js
new Promise(res => { console.log('a'); res(); });
console.log('b');
```

以下 JS 代码输出什么（sort 数字）？
```js
console.log([10, 2, 1].sort());
console.log([10, 2, 1].sort((a, b) => a - b));
```

以下 JS 代码输出什么（解构）？
```js
const [a, , b] = [1, 2, 3];
console.log(a + b);
```

以下 JS 代码输出什么（可选链）？
```js
const o = { a: { b: 1 } };
console.log(o.a?.b, o.x?.y);
```

以下 JS 代码输出什么（对象键顺序）？
```js
const o = { 2: 'b', 1: 'a', x: 'c' };
console.log(Object.keys(o).join(','));
```

