function id<T>(v: T): T { return v; }
const a = id(42);
```

以下 JS 代码输出什么（WeakMap 键）？
```js
const wm = new WeakMap();
const k = {};
wm.set(k, 1);
console.log(wm.get(k));
```

以下 JS 代码输出什么（Proxy）？
```js
const p = new Proxy({}, { get(t, k) { return 'proxy'; } });
console.log(p.anything);
```

以下 JS 代码输出什么（生成器）？
```js
function* g() { yield 1; yield 2; }
const it = g();
console.log(it.next().value, it.next().value);
```

以下 JS 代码输出什么（模板字符串）？
```js
const n = 3;
console.log(`v=${n * 2}`);
```

以下 JS 代码输出什么（for...of vs for...in）？
```js
const o = { a: 1, b: 2 };
console.log([...Object.keys(o)].join(','), [...o].length);
```

以下 JS 代码输出什么（闭包计数器封装）？
```js
function counter() { let n = 0; return { inc: () => ++n, get: () => n }; }
const c = counter();
c.inc(); c.inc();
console.log(c.get());
```
